+/**
+ * Subdissector for Vendor Specific Header IEs (Information Elements)
+ */
+static int
+dissect_hie_vendor(tvbuff_t *tvb, packet_info *pinfo _U_, proto_tree *ies_tree, void *data _U_)
+{
+    proto_tree *tree = ieee802154_create_pie_tree(tvb, ies_tree, hf_ieee802154_hie_vendor, ett_ieee802154_hie_vendor);
+
+    guint      offset = 2;
+    guint      hie_length = tvb_reported_length(tvb) - 2;
+    tvbuff_t  *next_tvb;
+
+    proto_tree_add_item(tree, hf_ieee802154_hie_vendor_oui, tvb, offset, 3, ENC_LITTLE_ENDIAN);
+
+    offset += 3; /* adjust for vendor OUI */
+    hie_length -= 3;
+
+    next_tvb = tvb_new_subset_length(tvb, offset, hie_length);
+
+    call_data_dissector(next_tvb, pinfo, tree);
+
+    return tvb_reported_length(tvb);
+}
